using System;using System.IO;using System.Linq;using System.Net;using System.Threading;using System.Threading.Tasks;namespace ServiceTool{internal static class ServiceHostingTests{[STAThread]static int Main(){try{int n=0;string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"hosting-fixtures-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string exe=Path.Combine(root,"service.exe");File.WriteAllText(Path.Combine(root,"Config.xml"),"<Config><Port>8881</Port><PaymentServiceAddress>http://localhost:5125/</PaymentServiceAddress></Config>");var urls=ServiceHostingConfig.Read(exe);if(urls.Count!=1||new Uri(urls[0]).Port!=8881)throw new Exception("Config.xml own port detection");n++;File.WriteAllText(exe+".config","<configuration><system.serviceModel><services><service><host><baseAddresses><add baseAddress='http://localhost:18081/'/></baseAddresses></host></service></services></system.serviceModel></configuration>");if(!ServiceHostingConfig.Read(exe).Any(u=>new Uri(u).Port==18081))throw new Exception("WCF detection");n++;var listener=new System.Net.Sockets.TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var server=Task.Run(()=>{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){var reader=new StreamReader(stream);string line=reader.ReadLine();if(!line.StartsWith("GET /swagger/index.html "))throw new Exception("Swagger path");while(!String.IsNullOrEmpty(reader.ReadLine())){}byte[] body=System.Text.Encoding.UTF8.GetBytes("<html>Swagger UI swagger-ui</html>");byte[] header=System.Text.Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: "+body.Length+"\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(body,0,body.Length);}});try{if(ServiceSwagger.Find(new[]{"http://127.0.0.1:"+port+"/"},CancellationToken.None)==null)throw new Exception("Swagger not found");server.GetAwaiter().GetResult();n++;}finally{listener.Stop();}Console.WriteLine("PASS: "+n+" hosting XML/WCF/Swagger loopback checks. No services executed.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}